func  (this *binance) IsInverse(typeVar interface{}, optionalArgs ...interface{}) interface{}  {
    subType := ccxt.GetArg(optionalArgs, 0, nil)
    _ = subType
    if ccxt.IsTrue(ccxt.IsEqual(subType, nil)) {
        return (ccxt.IsEqual(typeVar, "delivery"))
    } else {
        return ccxt.IsEqual(subType, "inverse")
    }
}
