func  (this *binance) CreateExpiredOptionMarket(symbol interface{}) interface{}  {
    // support expired option contracts
    var settle interface{} = "USDT"
    var optionParts interface{} = ccxt.Split(symbol, "-")
    var symbolBase interface{} = ccxt.Split(symbol, "/")
    var base interface{} = nil
    if ccxt.IsTrue(ccxt.IsGreaterThan(ccxt.GetIndexOf(symbol, "/"), ccxt.OpNeg(1))) {
        base = this.SafeString(symbolBase, 0)
    } else {
        base = this.SafeString(optionParts, 0)
    }
    var expiry interface{} = this.SafeString(optionParts, 1)
    var strike interface{} = this.SafeInteger(optionParts, 2)
    var strikeAsString interface{} = this.SafeString(optionParts, 2)
    var optionType interface{} = this.SafeString(optionParts, 3)
    var datetime interface{} = this.ConvertExpireDate(expiry)
    var timestamp interface{} = this.Parse8601(datetime)
    return map[string]interface{} {
        "id": ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(base, "-"), expiry), "-"), strikeAsString), "-"), optionType),
        "symbol": ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(base, "/"), settle), ":"), settle), "-"), expiry), "-"), strikeAsString), "-"), optionType),
        "base": base,
        "quote": settle,
        "baseId": base,
        "quoteId": settle,
        "active": nil,
        "type": "option",
        "linear": nil,
        "inverse": nil,
        "spot": false,
        "swap": false,
        "future": false,
        "option": true,
        "margin": false,
        "contract": true,
        "contractSize": nil,
        "expiry": timestamp,
        "expiryDatetime": datetime,
        "optionType": ccxt.Ternary(ccxt.IsTrue((ccxt.IsEqual(optionType, "C"))), "call", "put"),
        "strike": strike,
        "settle": settle,
        "settleId": settle,
        "precision": map[string]interface{} {
            "amount": nil,
            "price": nil,
        },
        "limits": map[string]interface{} {
            "amount": map[string]interface{} {
                "min": nil,
                "max": nil,
            },
            "price": map[string]interface{} {
                "min": nil,
                "max": nil,
            },
            "cost": map[string]interface{} {
                "min": nil,
                "max": nil,
            },
        },
        "info": nil,
    }
}
func  (this *binance) Market(symbol interface{}) interface{}  {
    if ccxt.IsTrue(ccxt.IsEqual(this.Markets, nil)) {
        panic(ccxt.ExchangeError(ccxt.Add(this.Id, " markets not loaded")))
    }
    // defaultType has legacy support on binance
    var defaultType interface{} = this.SafeString(this.Options, "defaultType")
    var defaultSubType interface{} = this.SafeString(this.Options, "defaultSubType")
    var isLegacyLinear interface{} = ccxt.IsEqual(defaultType, "future")
    var isLegacyInverse interface{} = ccxt.IsEqual(defaultType, "delivery")
    var isLegacy interface{} = ccxt.IsTrue(isLegacyLinear) || ccxt.IsTrue(isLegacyInverse)
    if ccxt.IsTrue(ccxt.IsString(symbol)) {
        if ccxt.IsTrue(ccxt.InOp(this.Markets, symbol)) {
            var market interface{} = ccxt.GetValue(this.Markets, symbol)
            // begin diff
            if ccxt.IsTrue(ccxt.IsTrue(isLegacy) && ccxt.IsTrue(ccxt.GetValue(market, "spot"))) {
                var settle interface{} = ccxt.Ternary(ccxt.IsTrue(isLegacyLinear), ccxt.GetValue(market, "quote"), ccxt.GetValue(market, "base"))
                var futuresSymbol interface{} = ccxt.Add(ccxt.Add(symbol, ":"), settle)
                if ccxt.IsTrue(ccxt.InOp(this.Markets, futuresSymbol)) {
                    return ccxt.GetValue(this.Markets, futuresSymbol)
                }
            } else {
                return market
            }
        } else if ccxt.IsTrue(ccxt.InOp(this.Markets_by_id, symbol)) {
            var markets interface{} = ccxt.GetValue(this.Markets_by_id, symbol)
            // begin diff
            if ccxt.IsTrue(isLegacyLinear) {
                defaultType = "linear"
            } else if ccxt.IsTrue(isLegacyInverse) {
                defaultType = "inverse"
            } else if ccxt.IsTrue(ccxt.IsEqual(defaultType, nil)) {
                defaultType = defaultSubType
            }
            // end diff
            for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(markets)); i++ {
                var market interface{} = ccxt.GetValue(markets, i)
                if ccxt.IsTrue(ccxt.GetValue(market, defaultType)) {
                    return market
                }
            }
            return ccxt.GetValue(markets, 0)
        } else if ccxt.IsTrue(ccxt.IsTrue((ccxt.IsGreaterThan(ccxt.GetIndexOf(symbol, "/"), ccxt.OpNeg(1)))) && ccxt.IsTrue((ccxt.IsLessThan(ccxt.GetIndexOf(symbol, ":"), 0)))) {
            // support legacy symbols
            basequoteVariable := ccxt.Split(symbol, "/");
            base := ccxt.GetValue(basequoteVariable,0);
            quote := ccxt.GetValue(basequoteVariable,1)
            var settle interface{} = ccxt.Ternary(ccxt.IsTrue((ccxt.IsEqual(quote, "USD"))), base, quote)
            var futuresSymbol interface{} = ccxt.Add(ccxt.Add(symbol, ":"), settle)
            if ccxt.IsTrue(ccxt.InOp(this.Markets, futuresSymbol)) {
                return ccxt.GetValue(this.Markets, futuresSymbol)
            }
        } else if ccxt.IsTrue(ccxt.IsTrue((ccxt.IsGreaterThan(ccxt.GetIndexOf(symbol, "-C"), ccxt.OpNeg(1)))) || ccxt.IsTrue((ccxt.IsGreaterThan(ccxt.GetIndexOf(symbol, "-P"), ccxt.OpNeg(1))))) {
            return this.CreateExpiredOptionMarket(symbol)
        }
    }
    panic(ccxt.BadSymbol(ccxt.Add(ccxt.Add(this.Id, " does not have market symbol "), symbol)))
}
func  (this *binance) SafeMarket(optionalArgs ...interface{}) interface{}  {
    marketId := ccxt.GetArg(optionalArgs, 0, nil)
    _ = marketId
    market := ccxt.GetArg(optionalArgs, 1, nil)
    _ = market
    delimiter := ccxt.GetArg(optionalArgs, 2, nil)
    _ = delimiter
    marketType := ccxt.GetArg(optionalArgs, 3, nil)
    _ = marketType
    var isOption interface{} = ccxt.IsTrue((!ccxt.IsEqual(marketId, nil))) && ccxt.IsTrue((ccxt.IsTrue((ccxt.IsGreaterThan(ccxt.GetIndexOf(marketId, "-C"), ccxt.OpNeg(1)))) || ccxt.IsTrue((ccxt.IsGreaterThan(ccxt.GetIndexOf(marketId, "-P"), ccxt.OpNeg(1))))))
    if ccxt.IsTrue(ccxt.IsTrue(isOption) && !ccxt.IsTrue((ccxt.InOp(this.Markets_by_id, marketId)))) {
        // handle expired option contracts
        return this.CreateExpiredOptionMarket(marketId)
    }
    return this.Exchange.SafeMarket(marketId, market, delimiter, marketType)
}
func  (this *binance) CostToPrecision(symbol interface{}, cost interface{}) interface{}  {
    return this.DecimalToPrecision(cost, ccxt.TRUNCATE, ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Markets, symbol), "precision"), "quote"), this.PrecisionMode, this.PaddingMode)
}
func  (this *binance) CurrencyToPrecision(code interface{}, fee interface{}, optionalArgs ...interface{}) interface{}  {
    // info is available in currencies only if the user has configured his api keys
    networkCode := ccxt.GetArg(optionalArgs, 0, nil)
    _ = networkCode
    if ccxt.IsTrue(!ccxt.IsEqual(this.SafeValue(ccxt.GetValue(this.Currencies, code), "precision"), nil)) {
        return this.DecimalToPrecision(fee, ccxt.TRUNCATE, ccxt.GetValue(ccxt.GetValue(this.Currencies, code), "precision"), this.PrecisionMode, this.PaddingMode)
    } else {
        return this.NumberToString(fee)
    }
}
func  (this *binance) Nonce() interface{}  {
    return ccxt.Subtract(this.Milliseconds(), ccxt.GetValue(this.Options, "timeDifference"))
}
