func  (this *binance) GetExceptionsByUrl(url interface{}, exactOrBroad interface{}) interface{}  {
    var marketType interface{} = nil
    var hostname interface{} = ccxt.Ternary(ccxt.IsTrue((!ccxt.IsEqual(this.Hostname, nil))), this.Hostname, "binance.com")
    if ccxt.IsTrue(ccxt.IsTrue(ccxt.StartsWith(url, ccxt.Add(ccxt.Add("https://api.", hostname), "/"))) || ccxt.IsTrue(ccxt.StartsWith(url, "https://testnet.binance.vision"))) {
        marketType = "spot"
    } else if ccxt.IsTrue(ccxt.IsTrue(ccxt.StartsWith(url, ccxt.Add(ccxt.Add("https://dapi.", hostname), "/"))) || ccxt.IsTrue(ccxt.StartsWith(url, "https://testnet.binancefuture.com/dapi"))) {
        marketType = "inverse"
    } else if ccxt.IsTrue(ccxt.IsTrue(ccxt.StartsWith(url, ccxt.Add(ccxt.Add("https://fapi.", hostname), "/"))) || ccxt.IsTrue(ccxt.StartsWith(url, "https://testnet.binancefuture.com/fapi"))) {
        marketType = "linear"
    } else if ccxt.IsTrue(ccxt.StartsWith(url, ccxt.Add(ccxt.Add("https://eapi.", hostname), "/"))) {
        marketType = "option"
    } else if ccxt.IsTrue(ccxt.StartsWith(url, ccxt.Add(ccxt.Add("https://papi.", hostname), "/"))) {
        marketType = "portfolioMargin"
    }
    if ccxt.IsTrue(!ccxt.IsEqual(marketType, nil)) {
        var exceptionsForMarketType interface{} = this.SafeDict(this.Exceptions, marketType, map[string]interface{} {})
        return this.SafeDict(exceptionsForMarketType, exactOrBroad, map[string]interface{} {})
    }
    return map[string]interface{} {}
}
func  (this *binance) HandleErrors(code interface{}, reason interface{}, url interface{}, method interface{}, headers interface{}, body interface{}, response interface{}, requestHeaders interface{}, requestBody interface{}) interface{}  {
    if ccxt.IsTrue(ccxt.IsTrue((ccxt.IsEqual(code, 418))) || ccxt.IsTrue((ccxt.IsEqual(code, 429)))) {
        panic(ccxt.DDoSProtection(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(this.Id, " "), ccxt.ToString(code)), " "), reason), " "), body)))
    }
    // error response in a form: { "code": -1013, "msg": "Invalid quantity." }
    // following block cointains legacy checks against message patterns in "msg" property
    // will switch "code" checks eventually, when we know all of them
    if ccxt.IsTrue(ccxt.IsGreaterThanOrEqual(code, 400)) {
        if ccxt.IsTrue(ccxt.IsGreaterThanOrEqual(ccxt.GetIndexOf(body, "Price * QTY is zero or less"), 0)) {
            panic(ccxt.InvalidOrder(ccxt.Add(ccxt.Add(this.Id, " order cost = amount * price is zero or less "), body)))
        }
        if ccxt.IsTrue(ccxt.IsGreaterThanOrEqual(ccxt.GetIndexOf(body, "LOT_SIZE"), 0)) {
            panic(ccxt.InvalidOrder(ccxt.Add(ccxt.Add(this.Id, " order amount should be evenly divisible by lot size "), body)))
        }
        if ccxt.IsTrue(ccxt.IsGreaterThanOrEqual(ccxt.GetIndexOf(body, "PRICE_FILTER"), 0)) {
            panic(ccxt.InvalidOrder(ccxt.Add(ccxt.Add(this.Id, " order price is invalid, i.e. exceeds allowed price precision, exceeds min price or max price limits or is invalid value in general, use this.priceToPrecision (symbol, amount) "), body)))
        }
    }
    if ccxt.IsTrue(ccxt.IsEqual(response, nil)) {
        return nil  // fallback to default error handler
    }
    // response in format {'msg': 'The coin does not exist.', 'success': true/false}
    var success interface{} = this.SafeBool(response, "success", true)
    if !ccxt.IsTrue(success) {
        var messageNew interface{} = this.SafeString(response, "msg")
        var parsedMessage interface{} = nil
        if ccxt.IsTrue(!ccxt.IsEqual(messageNew, nil)) {
            
            {		 func(this *binance) (ret_ interface{}) {
            		defer func() {
            			if e := recover(); e != nil {
                            if e == "break" {
            				    return
            			    }
            				ret_ = func(this *binance) interface{} {
            					// catch block:
                                                // do nothing
                            parsedMessage = nil
                                return nil
            				}(this)
            			}
            		}()
            		// try block:
                                    parsedMessage = ccxt.JsonParse(messageNew)
            		return nil
            	}(this)
                
            }
            if ccxt.IsTrue(!ccxt.IsEqual(parsedMessage, nil)) {
                response = parsedMessage
            }
        }
    }
    var message interface{} = this.SafeString(response, "msg")
    if ccxt.IsTrue(!ccxt.IsEqual(message, nil)) {
        this.ThrowExactlyMatchedException(this.GetExceptionsByUrl(url, "exact"), message, ccxt.Add(ccxt.Add(this.Id, " "), message))
        this.ThrowExactlyMatchedException(ccxt.GetValue(this.Exceptions, "exact"), message, ccxt.Add(ccxt.Add(this.Id, " "), message))
        this.ThrowBroadlyMatchedException(this.GetExceptionsByUrl(url, "broad"), message, ccxt.Add(ccxt.Add(this.Id, " "), message))
        this.ThrowBroadlyMatchedException(ccxt.GetValue(this.Exceptions, "broad"), message, ccxt.Add(ccxt.Add(this.Id, " "), message))
    }
    // checks against error codes
    var err interface{} = this.SafeString(response, "code")
    if ccxt.IsTrue(!ccxt.IsEqual(err, nil)) {
        // https://github.com/ccxt/ccxt/issues/6501
        // https://github.com/ccxt/ccxt/issues/7742
        if ccxt.IsTrue(ccxt.IsTrue((ccxt.IsEqual(err, "200"))) || ccxt.IsTrue(ccxt.Precise.StringEquals(err, "0"))) {
            return nil
        }
        // a workaround for {"code":-2015,"msg":"Invalid API-key, IP, or permissions for action."}
        // despite that their message is very confusing, it is raised by Binance
        // on a temporary ban, the API key is valid, but disabled for a while
        if ccxt.IsTrue(ccxt.IsTrue((ccxt.IsEqual(err, "-2015"))) && ccxt.IsTrue(ccxt.GetValue(this.Options, "hasAlreadyAuthenticatedSuccessfully"))) {
            panic(ccxt.DDoSProtection(ccxt.Add(ccxt.Add(this.Id, " "), body)))
        }
        var feedback interface{} = ccxt.Add(ccxt.Add(this.Id, " "), body)
        if ccxt.IsTrue(ccxt.IsEqual(message, "No need to change margin type.")) {
            panic(ccxt.MarginModeAlreadySet(feedback))
        }
        this.ThrowExactlyMatchedException(this.GetExceptionsByUrl(url, "exact"), err, feedback)
        this.ThrowExactlyMatchedException(ccxt.GetValue(this.Exceptions, "exact"), err, feedback)
        panic(ccxt.ExchangeError(feedback))
    }
    if !ccxt.IsTrue(success) {
        panic(ccxt.ExchangeError(ccxt.Add(ccxt.Add(this.Id, " "), body)))
    }
    if ccxt.IsTrue(ccxt.IsArray(response)) {
        // cancelOrders returns an array like this: [{"code":-2011,"msg":"Unknown order sent."}]
        var arrayLength interface{} =         ccxt.GetArrayLength(response)
        if ccxt.IsTrue(ccxt.IsEqual(arrayLength, 1)) {
            var element interface{} = ccxt.GetValue(response, 0)
            var errorCode interface{} = this.SafeString(element, "code")
            if ccxt.IsTrue(!ccxt.IsEqual(errorCode, nil)) {
                this.ThrowExactlyMatchedException(this.GetExceptionsByUrl(url, "exact"), errorCode, ccxt.Add(ccxt.Add(this.Id, " "), body))
                this.ThrowExactlyMatchedException(ccxt.GetValue(this.Exceptions, "exact"), errorCode, ccxt.Add(ccxt.Add(this.Id, " "), body))
            }
        }
    }
    return nil
}
func  (this *binance) CalculateRateLimiterCost(api interface{}, method interface{}, path interface{}, params interface{}, optionalArgs ...interface{}) interface{}  {
    config := ccxt.GetArg(optionalArgs, 0, map[string]interface{} {})
    _ = config
    if ccxt.IsTrue(ccxt.IsTrue((ccxt.InOp(config, "noCoin"))) && !ccxt.IsTrue((ccxt.InOp(params, "coin")))) {
        return ccxt.GetValue(config, "noCoin")
    } else if ccxt.IsTrue(ccxt.IsTrue((ccxt.InOp(config, "noSymbol"))) && !ccxt.IsTrue((ccxt.InOp(params, "symbol")))) {
        return ccxt.GetValue(config, "noSymbol")
    } else if ccxt.IsTrue(ccxt.IsTrue((ccxt.InOp(config, "noPoolId"))) && !ccxt.IsTrue((ccxt.InOp(params, "poolId")))) {
        return ccxt.GetValue(config, "noPoolId")
    } else if ccxt.IsTrue(ccxt.IsTrue((ccxt.InOp(config, "byLimit"))) && ccxt.IsTrue((ccxt.InOp(params, "limit")))) {
        var limit interface{} = ccxt.GetValue(params, "limit")
        var byLimit interface{} = ccxt.GetValue(config, "byLimit")
        for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(byLimit)); i++ {
            var entry interface{} = ccxt.GetValue(byLimit, i)
            if ccxt.IsTrue(ccxt.IsLessThanOrEqual(limit, ccxt.GetValue(entry, 0))) {
                return ccxt.GetValue(entry, 1)
            }
        }
    }
    return this.SafeValue(config, "cost", 1)
}
